(function(){
  'use strict';
  const menuBtn=document.querySelector('[data-menu-toggle]');
  const nav=document.querySelector('[data-nav-links]');
  const closeMenu=()=>{ if(nav){ nav.classList.remove('open'); document.body.classList.remove('nav-open'); } if(menuBtn){ menuBtn.setAttribute('aria-expanded','false'); menuBtn.classList.remove('is-open'); } };
  if(menuBtn&&nav){
    menuBtn.addEventListener('click',()=>{
      const open=nav.classList.toggle('open');
      menuBtn.setAttribute('aria-expanded',String(open));
      menuBtn.classList.toggle('is-open',open);
      document.body.classList.toggle('nav-open',open);
    });
    nav.addEventListener('click',e=>{ if(e.target.closest('a')) closeMenu(); });
    window.addEventListener('resize',()=>{ if(window.innerWidth>820) closeMenu(); });
  }
  document.addEventListener('click',e=>{
    document.querySelectorAll('.lang-menu[open]').forEach(d=>{ if(!d.contains(e.target)) d.removeAttribute('open'); });
    if(nav&&menuBtn&&nav.classList.contains('open')&&!nav.contains(e.target)&&!menuBtn.contains(e.target)) closeMenu();
  });
  document.addEventListener('keydown',e=>{
    if(e.key==='Escape'){
      closeMenu();
      document.querySelectorAll('.lang-menu[open]').forEach(d=>d.removeAttribute('open'));
    }
  });
  const search=document.querySelector('[data-tool-search]');
  if(search){
    const cards=[...document.querySelectorAll('[data-tool-card]')];
    const empty=document.querySelector('[data-no-results]');
    const apply=()=>{
      const q=search.value.trim().toLocaleLowerCase();
      let visible=0;
      cards.forEach(card=>{
        const show=!q||card.textContent.toLocaleLowerCase().includes(q);
        card.hidden=!show;
        if(show) visible++;
      });
      if(empty) empty.style.display=visible?'none':'block';
      document.querySelectorAll('[data-tool-group]').forEach(group=>{
        const groupCards=[...group.querySelectorAll('[data-tool-card]')];
        group.hidden=Boolean(q)&&!groupCards.some(card=>!card.hidden);
      });
    };
    search.addEventListener('input',apply);
  }
  document.querySelectorAll('[data-year]').forEach(el=>{ el.textContent=String(new Date().getFullYear()); });
  const suggestion=document.querySelector('[data-language-suggestion]');
  if(suggestion){
    const lang=(navigator.language||'en').toLowerCase();
    const code=lang.startsWith('ar')?'ar':lang.startsWith('es')?'es':lang.startsWith('pt')?'pt-br':lang.startsWith('fr')?'fr':'en';
    const link=suggestion.querySelector(`[data-lang="${code}"]`);
    if(link){ suggestion.hidden=false; link.hidden=false; }
  }
})();

/* Services / tools dropdown: hover-first on desktop, click on touch/mobile, keyboard safe. */
(function(){
  'use strict';
  const menus=[...document.querySelectorAll('[data-tools-menu]')];
  if(!menus.length)return;
  const desktop=()=>window.matchMedia('(min-width:821px)').matches;
  const timers=new WeakMap();
  const clearClose=menu=>{const t=timers.get(menu);if(t){clearTimeout(t);timers.delete(menu);}};
  const setOpen=(menu,open,hover=false)=>{
    clearClose(menu);
    const trigger=menu.querySelector('[data-tools-trigger]');
    menu.classList.toggle('open',open);
    if(hover)menu.dataset.hoverOpen=open?'true':'false';
    else if(!open)delete menu.dataset.hoverOpen;
    if(trigger)trigger.setAttribute('aria-expanded',String(open));
  };
  const closeOthers=current=>menus.forEach(menu=>{if(menu!==current)setOpen(menu,false);});
  const scheduleClose=menu=>{
    clearClose(menu);
    const t=setTimeout(()=>setOpen(menu,false),260);
    timers.set(menu,t);
  };
  menus.forEach(menu=>{
    const trigger=menu.querySelector('[data-tools-trigger]');
    const dropdown=menu.querySelector('[data-tools-dropdown]');
    if(!trigger)return;

    /* Desktop is genuinely hover-first: click is not required and never closes an open hover menu. */
    trigger.addEventListener('click',e=>{
      e.preventDefault();
      if(desktop()){
        closeOthers(menu);
        setOpen(menu,true,true);
        return;
      }
      const next=!menu.classList.contains('open');
      closeOthers(menu);setOpen(menu,next);
    });

    trigger.addEventListener('pointerenter',()=>{
      if(!desktop())return;
      clearClose(menu);closeOthers(menu);setOpen(menu,true,true);
    });
    trigger.addEventListener('pointerleave',()=>{if(desktop())scheduleClose(menu);});
    if(dropdown){
      dropdown.addEventListener('pointerenter',()=>{if(desktop()){clearClose(menu);setOpen(menu,true,true);}});
      dropdown.addEventListener('pointerleave',()=>{if(desktop())scheduleClose(menu);});
    }
    menu.addEventListener('focusin',()=>{if(desktop()){clearClose(menu);closeOthers(menu);setOpen(menu,true);}});
    menu.addEventListener('focusout',e=>{if(desktop()&&!menu.contains(e.relatedTarget))scheduleClose(menu);});
    menu.addEventListener('click',e=>{if(e.target.closest('.tools-dropdown a'))setOpen(menu,false);});
  });
  document.addEventListener('click',e=>{menus.forEach(menu=>{if(!menu.contains(e.target))setOpen(menu,false);});});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')menus.forEach(menu=>setOpen(menu,false));});
  window.addEventListener('resize',()=>{menus.forEach(menu=>setOpen(menu,false));});
})();


/* UX16 — mobile header hides on downward scroll and returns immediately on upward scroll. */
(function(){
  'use strict';
  const header=document.querySelector('.site-header');if(!header)return;
  const mq=window.matchMedia('(max-width:820px)');let lastY=Math.max(0,window.scrollY),ticking=false;
  const show=()=>header.classList.remove('is-scroll-hidden');
  const update=()=>{
    const y=Math.max(0,window.scrollY),delta=y-lastY,menuOpen=document.body.classList.contains('nav-open');
    if(!mq.matches||menuOpen||y<96)show();
    else if(delta>7&&y>150)header.classList.add('is-scroll-hidden');
    else if(delta<-5)show();
    lastY=y;ticking=false;
  };
  window.addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(update);}},{passive:true});
  window.addEventListener('resize',()=>{lastY=Math.max(0,window.scrollY);if(!mq.matches)show();},{passive:true});
  document.addEventListener('click',e=>{if(e.target.closest('[data-menu-toggle]'))show();});
})();
